#include "all_your_base.h"

#include <stdexcept>

namespace all_your_base {

std::vector<unsigned int> convert(unsigned int input_base,
                                  const std::vector<unsigned int>& input_digits,
                                  unsigned int output_base) {
    if (input_base < 2 || output_base < 2) {
        throw std::invalid_argument("bases must be at least 2");
    }

    for (unsigned int digit : input_digits) {
        if (digit >= input_base) {
            throw std::invalid_argument("digit is not valid in the input base");
        }
    }

    std::vector<unsigned int> value;
    for (unsigned int digit : input_digits) {
        if (!value.empty() || digit != 0) {
            value.push_back(digit);
        }
    }

    std::vector<unsigned int> output_digits;
    while (!value.empty()) {
        unsigned int remainder = 0;
        std::vector<unsigned int> quotient;
        bool significant_digit_found = false;

        for (unsigned int digit : value) {
            const unsigned int current = remainder * input_base + digit;
            const unsigned int quotient_digit = current / output_base;
            remainder = current % output_base;

            if (significant_digit_found || quotient_digit != 0) {
                significant_digit_found = true;
                quotient.push_back(quotient_digit);
            }
        }

        output_digits.push_back(remainder);
        value = quotient;
    }

    return output_digits;
}

}  // namespace all_your_base
EOF
